268	    init_list_head(&new_pcb->timer.list);
269	    new_pcb->binsem_num = 0;
270	    new_pcb->pid = process_id++;
271	    new_pcb->type = USER_PROCESS;
272	    new_pcb->status = TASK_READY;
273	    new_pcb->mode = mode;
274	    new_pcb->priority = 1;
