338	/* Common part of exiting and being killed: hand back the semaphores, wake
339	 * everybody who waits for this task and disarm its sleep timer. */
340	static void release_resources(pcb_t *task)
341	{
342	    release_binsem(task);
343	    abandon_binsem_wait(task);
344	
345	    while (!list_empty(&task->wait_list)) {
346	        do_unblock(task->wait_list.next);
347	    }
348	
349	    /* a sleeping task may still have an armed timer */
350	    list_del(&task->timer.list);
351	}
