353	/*
354	 * Destroy `task` completely: give back everything it holds, throw away its
355	 * address space and mark the pcb.  The kernel stack survives a little longer,
356	 * because a task that has just stopped running is still standing on it: it is
357	 * released either by the parent in do_waitpid() or by the idle task of core 0.
358	 */
359	static void destroy_task(pcb_t *task, int still_on_kernel_stack)
360	{
361	    release_resources(task);
362	
363	    free_process_user_page(task->pgdir);
364	    task->pgdir = (PTE*)PGDIR_PA;
365	
366	    list_del(&task->list);
367	
368	    if (task->mode == ENTER_ZOMBIE_ON_EXIT) {
369	        /* the parent reaps us in do_waitpid() */
370	        task->status = TASK_ZOMBIE;
371	    } else {
372	        task->status = TASK_EXITED;
373	        if (still_on_kernel_stack) {
374	            /* it is still unwinding out of the kernel: let the idle task of
375	             * core 0 have it only after the next scheduling round */
376	            pending_reap[cpu_id] = task;
377	        } else {
378	            list_add_tail(&task->list, &kernel_pcb[0].wait_list);
379	        }
380	    }
381	}
