388	    /* We still run in this address space and on this kernel stack, so the
389	     * teardown has to wait until scheduler() has switched away from us. */
390	    list_del(&cur->list);
391	    pending_kill[cpu_id] = cur;
392	    scheduler();
393	
394	    enable_preempt();
395	}
